const puml = `@startuml
title <size:24>System Context View: Library</size>

set separator none
left to right direction

<style>
  root {
    BackgroundColor: #ffffff
    FontColor: #444444
  }
</style>

!include <C4/C4>
!include <C4/C4_Context>

Person(Patron, "Patron", $descr="Borrows books at the library.", $tags="", $link="")
System(Library, "Library", $descr="Manages books and loans.", $tags="", $link="")

Rel(Patron, Library, "Browses the catalogue through", $techn="HTTPS", $tags="", $link="")

SHOW_LEGEND(true)
hide stereotypes
@enduml`;

const res = await fetch("https://www.plantuml.com/plantuml/png/", {
  method: "POST",
  headers: { "Content-Type": "text/plain" },
  body: puml,
});
if (!res.ok) {
  return { error: res.status, text: (await res.text()).slice(0, 2000) };
}
const bytes = new Uint8Array(await res.arrayBuffer());
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
let out = "";
for (let i = 0; i < bytes.length; i += 3) {
  const b0 = bytes[i], b1 = i + 1 < bytes.length ? bytes[i + 1] : 0, b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
  out += B64[b0 >> 2];
  out += B64[((b0 & 3) << 4) | (b1 >> 4)];
  out += i + 1 < bytes.length ? B64[((b1 & 15) << 2) | (b2 >> 6)] : "=";
  out += i + 2 < bytes.length ? B64[b2 & 63] : "=";
}
return { size: bytes.length, b64: out };

